WITH src AS (SELECT * FROM inventory WHERE last_restock >= '2024-09-01'), Agg AS (SELECT CASE WHEN quantity >= 247 THEN 'high' WHEN quantity >= 57 THEN 'mid' ELSE 'low' END AS quantity_bucket, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM src GROUP BY CASE WHEN quantity >= 247 THEN 'high' WHEN quantity >= 57 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, stddev_quantity FROM Agg ORDER BY quantity_bucket, stddev_quantity DESC;
